package cn.zhuatech.llmops.controller; import cn.zhuatech.llmops.common.ApiResponse; import cn.zhuatech.llmops.dto.LlmOpsDto.*; import cn.zhuatech.llmops.service.LlmOpsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final LlmOpsService service;public OperationsAdminController(LlmOpsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
